CREATE POLICY "studio staff read private pasko files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id IN ('pasko-orders', 'pasko-media') AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "studio staff upload private pasko files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id IN ('pasko-orders', 'pasko-media') AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "studio staff update private pasko files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id IN ('pasko-orders', 'pasko-media') AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id IN ('pasko-orders', 'pasko-media') AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "studio staff delete private pasko files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id IN ('pasko-orders', 'pasko-media') AND public.has_role(auth.uid(), 'admin'));